WITH remaining_keys AS (SELECT order_id FROM payments INTERSECT ALL SELECT order_id FROM payments WHERE amount >= 1190), reconciled AS (SELECT s.* FROM payments s INNER JOIN remaining_keys k ON s.order_id = k.order_id) SELECT s.id, s.order_id, s.method, s.status, (SELECT SUM(t2.unit_price) FROM order_items t2 WHERE t2.order_id = s.order_id) AS sum_order_item_unit_price FROM reconciled s ORDER BY status DESC NULLS FIRST
